"""Build metadata for the checked-in API checkpoint source files. No host imports."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
LESSONS = ROOT / "lesson_materials/week_07_api_checkpoints"
U = "https://dev.epicgames.com/documentation/en-us/unreal-engine/python-api/class/"
B = "https://docs.blender.org/api/5.1/"
rows = [
    ("UE01", "01 Unreal objects", "Unreal host and project", "ue/UE01_host.py", "Unreal editor open, Python Script Plugin enabled.", "Hello from Unreal, the engine version and the actual project directory.", "Read only. Rerun freely.", "Change the greeting and run again.", "SystemLibrary"),
    ("UE02", "01 Unreal objects", "Level selection", "ue/UE02_level_selection.py", "Select the target cube, then try an empty selection.", "Selected Actor count, labels and class names. Empty selection prints zero.", "Read only. Selection is manual.", "Select both cubes. Predict the count before running.", "EditorActorSubsystem"),
    ("UE03", "01 Unreal objects", "Actor, component and mesh", "ue/UE03_components.py", "Select a mesh Actor; repeat with a camera or light.", "Component count and shared mesh path. Actors without mesh components print zero.", "Read only. No dependency on UE02's variables.", "Select two cubes sharing a mesh. Compare their object labels and mesh paths.", "StaticMeshComponent"),
    ("UE04", "02 Unreal asset inspection", "Content Browser selection", "ue/UE04_asset_selection.py", "Select assets in the Content Browser, independently of the Outliner.", "Asset count, names, class names and object paths.", "Read only. Rerun after changing asset selection.", "Select one texture and one mesh. Which class names print?", "EditorUtilityLibrary"),
    ("UE05", "02 Unreal asset inspection", "Texture editor properties", "ue/UE05_texture_properties.py", "Select textures; include a non-texture to test eligibility.", "Texture/skipped counts, compression and sRGB values.", "Read only. Shared texture assets remain unchanged.", "Compare a normal map with a color texture.", "Texture"),
    ("UE06", "02 Unreal asset inspection", "Read-only validation", "ue/UE06_validation_report.py", "Select textures. The prepared material tool uses the suffix _Normal.", "Every mismatching _Normal texture and final checked/mismatch counts. Zero checked is explicitly inconclusive.", "Read only. No repair or saving.", "Change only the suffix rule for your project. Predict which assets are eligible.", "Texture"),
    ("UE07", "02 Unreal asset inspection", "Disk paths and asset paths", "ue/UE07_paths.py", "Any Unreal project with the built-in BasicShapes cube available.", "Project Content disk folder and loaded /Engine object path.", "Read only. Loading the cube does not place an Actor.", "Which path could a filesystem function inspect?", "EditorAssetLibrary"),
    ("BL01", "03 Blender API comparison", "Blender host and selection", "blender/BL01_host_selection.py", "Blender Text Editor, preferably the prepared BridgeCompare.blend.", "Blender version, mode, selection count, object names/types.", "Read only. Rerun freely.", "Select a camera and a mesh together. Predict their types.", "bpy.context.html"),
    ("BL02", "03 Blender API comparison", "Object and mesh data", "blender/BL02_object_mesh.py", "Select at least one mesh object.", "Object location, mesh datablock name/users and source polygon count.", "Read only. No dependency on BL01's variables.", "With linked duplicates, compare Object names and mesh data names.", "bpy.types.Object.html"),
    ("BL03", "03 Blender API comparison", "Evaluated geometry", "blender/BL03_evaluated_mesh.py", "Object Mode with exactly one mesh selected. A modifier can make the contrast visible.", "Source and evaluated polygon counts. They can be equal without a topology-changing modifier.", "Read only. Temporary mesh released in finally; modifier is not applied.", "Compare counts with a prepared subdivision modifier enabled and disabled.", "bpy.types.Object.html"),
    ("BL04", "03 Blender API comparison", "One FBX export", "blender/BL04_export_fbx.py", "Object Mode, one unrigged mesh, no shape keys. FBX exporter available.", "A nonempty FBX in a new temporary folder; exact path prints.", "Writes a new temporary folder each run. Remove only the printed lesson folder afterward. No scene save.", "Read use_selection and bake_anim. Predict their effect on scope.", "bpy.ops.export_scene.html"),
    ("UE11", "04 Import preparation and execution", "Prepare an import task", "ue/UE11_import_task.py", "Week07UnrealPython project with Samples/Bridge/Handoffs included.", "Prepared source and destination. No new Unreal asset.", "Read only. Constructs task/options objects but does not execute an import.", "Change destination_name in this preparation-only example. What would it identify?", "AssetImportTask"),
    ("UE12", "04 Import preparation and execution", "Import and inspect", "ue/UE12_import_and_verify.py", "Same project, PIE stopped, /Game/Week07/APILessons/SM_API_Wedge absent.", "One unsaved StaticMesh at the exact lesson path, returned paths and bounds.", "Creates an unsaved lesson asset. Refuses repeat overwrite. After inspection manually remove only that lesson asset, or use a fresh disposable project copy. Do not assume Undo reverses import.", "Compare printed bounds with the supplied wedge's 120 x 60 x 180 cm reference. No size check is implied by file existence.", "AssetImportTask"),
    ("UE08", "05 Controlled edits and verification", "One material override", "ue/UE08_material_override.py", "W07_MaterialVFXLab, PIE stopped. Select only tagged W07_Crate_Target and one existing material/instance.", "Target slot zero changes; old/new materials print. Protected cube remains unchanged.", "One viewport Undo restores the assignment. No new asset or save. Already assigned material creates no new Undo entry.", "Try selecting the protected cube. Confirm the check blocks before editing.", "ScopedEditorTransaction"),
    ("UE09", "05 Controlled edits and verification", "Material parameter readback", "ue/UE09_material_readback.py", "Select exactly one MaterialInstanceConstant in the Content Browser.", "Texture parameter names and resolved texture paths, or None. Zero parameters prints zero.", "Read only. Use the instance from the prepared Material/VFX demo.", "Compare an expected texture mapping with the reported value.", "MaterialEditingLibrary"),
    ("UE10", "05 Controlled edits and verification", "Niagara component inspection", "ue/UE10_niagara_components.py", "Select the effects produced by the prepared VFX tool, or compare a non-effect Actor.", "Niagara component counts and referenced system paths. No effects are spawned.", "Read only. Use the prepared tool for placement and its demonstrated Undo.", "Would three successful placements establish GPU frame cost?", "NiagaraComponent"),
    ("PY01", "06 Connection to the full tool", "A preview snapshot", "python/PY01_preview_snapshot.py", "Ordinary Python, Unreal Python or Blender Python; no host module required.", "The changed target differs from the reviewed copy, so BLOCKED prints.", "Only local teaching dictionaries change. Rerun resets them.", "Comment out the target change and predict the other branch.", None),
]
steps = []
for ident, stage, title, file, setup, expected, recovery, experiment, reference in rows:
    host = "blender" if ident.startswith("BL") else "python" if ident.startswith("PY") else "unreal"
    url = B + reference if host == "blender" else U + reference + "?application_version=5.7" if reference else None
    source = (LESSONS / file).read_text(encoding="utf-8")
    blocks = [line.removeprefix("# %% ").strip() for line in source.splitlines() if line.startswith("# %% ")]
    steps.append(dict(id=ident, stage=stage, title=title, file=file, host=host, prerequisites=setup,
                      expected=expected, recovery=recovery, experiment=experiment, blocks=blocks,
                      namespace="Independent full file. Blocks share this file's namespace in displayed order.",
                      references=[url] if url else []))
(LESSONS / "sequence.json").write_text(json.dumps({"schema_version": 1, "steps": steps}, indent=2) + "\n", encoding="utf-8")
print(f"Catalogued {len(steps)} API checkpoints")
